              <div><label class="l" data-i18n="rej.dup">Duplicate invoices</label><label class="togg" style="margin-top:7px"><input type="checkbox" id="rj-dup" checked> <span data-i18n="rej.dup">Duplicates</span></label></div>
            </div>
